package main

import (
	"fmt"
	"html/template"
	"log"
	"net/http"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
)

// TerraformProvider resource schema for managing dashboard widgets
func resourceDashboardWidget() *schema.Resource {
	return &schema.Resource{
		Create: resourceDashboardWidgetCreate,
		Read:   resourceDashboardWidgetRead,
		Update: resourceDashboardWidgetUpdate,
		Delete: resourceDashboardWidgetDelete,
		Schema: map[string]*schema.Schema{
			"title": {
				Type:     schema.TypeString,
				Required: true,
			},
			"description": {
				Type:     schema.TypeString,
				Optional: true,
			},
			"query": {
				Type:     schema.TypeString,
				Required: true,
			},
		},
	}
}

// Dashboard rendering server - serves widget previews
type DashboardServer struct {
	widgets map[string]*Widget
}

type Widget struct {
	Title       string
	Description string
	Query       string
}

// Format string vulnerability: user-controlled title is used as format string
func (ds *DashboardServer) renderWidget(w http.ResponseWriter, r *http.Request) {
	widgetID := r.URL.Query().Get("id")
	userNote := r.URL.Query().Get("note")

	widget, exists := ds.widgets[widgetID]
	if !exists {
		http.Error(w, "Widget not found", 404)
		return
	}

	// BUG: Format string vulnerability - userNote used as format string
	// This allows injection of arbitrary content including script tags
	formattedNote := fmt.Sprintf(userNote, widget.Title, widget.Description)

	// Build response HTML with widget data
	responseHTML := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head><title>Widget Preview</title></head>
<body>
<div class="widget-container">
  <h1>%s</h1>
  <p class="description">%s</p>
  <div class="user-note">%s</div>
  <div class="query-display"><pre>%s</pre></div>
</div>
</body>
</html>`, widget.Title, widget.Description, formattedNote, widget.Query)

	w.Header().Set("Content-Type", "text/html")
	w.Write([]byte(responseHTML))
}

// Secondary endpoint with template - looks dangerous but is actually safe
func (ds *DashboardServer) renderSummary(w http.ResponseWriter, r *http.Request) {
	tmpl := template.Must(template.New("summary").Parse(`
		<html><body>
		{{range .}}<div>{{.Title}}: {{.Description}}</div>{{end}}
		</body></html>
	`))
	var widgetList []*Widget
	for _, widget := range ds.widgets {
		widgetList = append(widgetList, widget)
	}
	tmpl.Execute(w, widgetList)
}

func resourceDashboardWidgetCreate(d *schema.ResourceData, m interface{}) error {
	title := d.Get("title").(string)
	// Validation that looks like it helps but doesn't prevent the format string issue
	if strings.Contains(title, "$$") || len(title) > 200 {
		return fmt.Errorf("invalid title format")
	}
	d.SetId(fmt.Sprintf("widget-%s", title))
	return nil
}

func resourceDashboardWidgetRead(d *schema.ResourceData, m interface{}) error {
	return nil
}

func resourceDashboardWidgetUpdate(d *schema.ResourceData, m interface{}) error {
	return nil
}

func resourceDashboardWidgetDelete(d *schema.ResourceData, m interface{}) error {
	d.SetId("")
	return nil
}

func main() {
	ds := &DashboardServer{
		widgets: map[string]*Widget{
			"w1": {Title: "CPU Usage", Description: "System CPU metrics", Query: "avg(cpu_usage)"},
		},
	}
	http.HandleFunc("/widget", ds.renderWidget)
	http.HandleFunc("/summary", ds.renderSummary)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
